处理函数及属性:
{"aria-current": "{activeTab === tab.id ? "page" : undefined}", "aria-label": "{tab.label}", "className": "{
                          activeTab === tab.id
                            ? "admin-tab is-active"
                            : "admin-tab"
                        }", "key": "{tab.id}", "type": ""button"", "onClick": "{() => {
                          setActiveTab(tab.id);
                          setNavigationIntent("");
                          // C3：切标签清掉上一页残留的全局提示。
                          setError("");
                          setNotice("");
                          if (isCompactNavigation) {
                            setIsNavigationOpen(false);
                          }
                        }}"}

{"aria-label": "{`${ariaPrefix} 人物运动`}", "className": ""shot-table-select"", "disabled": "{readOnly}", "onChange": "{(event) => {
          const next = event.target.value as ShotMotion["subject_motion_state"];
          if (next) {
            onChange({ subject_motion_state: next });
          }
        }}", "value": """"}

{"aria-label": "{`${ariaPrefix} 人物运动`}", "className": ""shot-table-select"", "disabled": "{readOnly}", "onChange": "{(event) =>
          onChange({
            subject_motion_state: event.target
              .value as ShotMotion["subject_motion_state"],
          })
        }", "value": "{motion.subject_motion_state}"}

{"aria-label": "{`${ariaPrefix} 位移方向`}", "className": ""shot-table-select"", "disabled": "{readOnly}", "onChange": "{(event) =>
          onChange({
            subject_direction: event.target
              .value as ShotMotion["subject_direction"],
          })
        }", "value": "{motion.subject_direction}"}

{"aria-label": "{`${ariaPrefix} 运镜方式`}", "className": ""shot-table-select"", "disabled": "{readOnly}", "onChange": "{(event) =>
          onChange({
            camera_motion: event.target.value as ShotMotion["camera_motion"],
          })
        }", "value": "{motion.camera_motion}"}

{"aria-current": "{activePage === item.page ? "page" : undefined}", "className": "{
              activePage === item.page
                ? "nav-button nav-button--active"
                : "nav-button"
            }", "disabled": "{navigationDisabled}", "key": "{item.page}", "onClick": "{() => onNavigate(item.page)}", "type": ""button""}

{"aria-current": "{activePage === item.page ? "page" : undefined}", "className": "{
                    activePage === item.page
                      ? "sidebar-user__menu-item sidebar-user__menu-item--active"
                      : "sidebar-user__menu-item"
                  }", "disabled": "{navigationDisabled}", "key": "{item.page}", "onClick": "{() => navigateFromUserMenu(item.page)}", "type": ""button""}

{"aria-label": "{`查看人物 ${entry.display_name} 大图`}", "className": ""character-preview-card__cover"", "disabled": "{coverStatus === "loading"}", "onClick": "{() => {
                    if (cover && coverStatus === "error") {
                      void loadPreviewUrls([cover.assetId], true);
                      return;
                    }
                    setLightboxId(entry.identity_id);
                  }}", "type": ""button""}

{"aria-label": "{`查看${look.scene_name}五视图`}", "className": ""secondary-button"", "onClick": "{() =>
                            setExpandedSceneId((current) =>
                              current === look.persona_id
                                ? ""
                                : look.persona_id,
                            )
                          }", "type": ""button""}

{"aria-label": ""视频生成提示词内容"", "onChange": "{(event) => onPromptTextChange(event.target.value)}", "readOnly": "{
                  readOnly ||
                  busyAction === "compile" ||
                  busyAction === "prompt" ||
                  promptStatus === "LOCKED" ||
                  promptStatus === "USED"
                }", "rows": "{10}", "maxLength": "{7000}", "value": "{promptText}"}

{"disabled": "{
                  readOnly ||
                  promptDirty ||
                  promptStale ||
                  busy ||
                  promptStatus === "LOCKED" ||
                  promptStatus === "USED"
                }", "onClick": "{onLockPrompt}", "type": ""button""}

{"disabled": "{readOnly}", "type": "{field.secret && !isVisible ? "password" : "text"}", "value": "{values[field.name] ?? ""}", "placeholder": "{
                    field.secret && settings.configured
                      ? "已保存，留空不修改"
                      : field.placeholder
                  }", "onChange": "{(event) =>
                    setValues((current) => ({
                      ...current,
                      [field.name]: event.target.value,
                    }))
                  }"}

{"checked": "{selectedAssetId === candidate.asset_id}", "disabled": "{
                      readOnly ||
                      isSubmitting ||
                      !previewUrls[candidate.asset_id]
                    }", "name": ""source-frame"", "onChange": "{() => {
                      setSelectedAssetId(candidate.asset_id);
                      setStatus("已选择其他源画面，点击下方按钮应用。");
                    }}", "type": ""radio"", "value": "{candidate.asset_id}"}

{"aria-label": "{`确认为任务 ${task.id} 新增一次付费生成`}", "checked": "{taskPaymentConfirmed}", "disabled": "{taskActionBusy}", "onChange": "{(event) =>
                        onTaskPaymentConfirmationChange(
                          task.id,
                          event.target.checked,
                        )
                      }", "type": ""checkbox""}

{"type": ""button"", "onClick": "{() =>
                                  openAction({
                                    kind: "code",
                                    action: "suspend",
                                    codeId: item.code_id,
                                    status: item.status,
                                  })
                                }"}

{"type": ""button"", "onClick": "{() =>
                                  openAction({
                                    kind: "code",
                                    action: "resume",
                                    codeId: item.code_id,
                                    status: item.status,
                                  })
                                }"}

{"className": ""admin-action--danger"", "type": ""button"", "onClick": "{() =>
                                  openAction({
                                    kind: "code",
                                    action: "archive",
                                    codeId: item.code_id,
                                    status: item.status,
                                  })
                                }"}

{"className": ""admin-action--danger"", "type": ""button"", "onClick": "{() =>
                                  openAction({
                                    kind: "code",
                                    action: "revoke",
                                    codeId: item.code_id,
                                    status: item.status,
                                  })
                                }"}

{"aria-label": ""批准设备"", "type": ""button"", "onClick": "{() =>
                    onAction({
                      kind: "pairing",
                      codeId,
                      pairingId: pairing.pairing_request_id,
                      candidateName: pairing.display_name,
                    })
                  }"}

{"aria-label": "{
                    boundDevices.length === 1
                      ? `替换为${pairing.display_name}`
                      : `用${pairing.display_name}替换${device.display_name || `设备 #${device.slot_no}`}`
                  }", "type": ""button"", "key": "{device.device_id}", "onClick": "{() =>
                    onAction({
                      kind: "pairing",
                      codeId,
                      pairingId: pairing.pairing_request_id,
                      candidateName: pairing.display_name,
                      replaceDeviceId: device.device_id,
                      replaceDeviceName:
                        device.display_name || `设备 #${device.slot_no}`,
                    })
                  }"}

{"type": ""button"", "onClick": "{() =>
                          onAction({
                            kind: "device",
                            action: "unbind",
                            codeId,
                            deviceId: device.device_id,
                            deviceName,
                          })
                        }"}

{"className": ""admin-action--danger"", "type": ""button"", "onClick": "{() =>
                          onAction({
                            kind: "device",
                            action: "revoke",
                            codeId,
                            deviceId: device.device_id,
                            deviceName,
                          })
                        }"}

{"active": "{tab}", "ariaLabel": ""客户管理页签"", "items": "{tabs}", "onChange": "{setTab}", "actions": "{
          tab === "codes" && !readOnly ? (
            <button
              type="button"
              onClick={() => setShowGenerator((open) => !open)}
            >
              {showGenerator ? "收起生成表单" : "生成激活码"}
            </button>
          ) : undefined
        }"}

{"aria-label": "{`确认知晓大幅调价：${rateLabel(rate.subject)}`}", "checked": "{editing.ack}", "type": ""checkbox"", "onChange": "{(event) =>
                            setEditing({
                              ...editing,
                              ack: event.target.checked,
                            })
                          }"}

{"type": ""button"", "className": ""btn-secondary"", "onClick": "{() => {
                // A re-submitted form starts a fresh pairing attempt with a
                // fresh waiting-stage key.
                setPollKey("");
                setStage("form");
              }}"}

{"aria-current": "{tab === value ? "page" : undefined}", "className": "{tab === value ? "is-active" : ""}", "key": "{value}", "onClick": "{() => {
              setTab(value);
              if (value === "devices") {
                void onRefreshDevices();
              }
            }}", "type": ""button""}

{"className": ""secondary-button"", "disabled": "{!profile?.activation_code_masked}", "onClick": "{() =>
                  void copyText(
                    profile?.activation_code_masked ?? "",
                    "授权编号已复制。",
                  )
                }", "type": ""button""}

{"variant": ""outline"", "aria-label": "{`复刻 ${video.title}`}", "onClick": "{() => {
              patchDraft({ sourceId: video.id });
              navigate("replica", {
                selectedVideoId: video.id,
                returnTo: "viral",
              });
            }}"}

{"variant": ""outline"", "onClick": "{() =>
                  patchState({
                    favorites: saved
                      ? state.favorites.filter((id) => id !== video.id)
                      : [...state.favorites, video.id],
                  })
                }"}

{"accept": "".jpg,.jpeg,.png,.mp3,.mp4,.mov"", "aria-label": ""选择上传素材"", "hidden": "true", "onChange": "{(event) => {
            const file = event.target.files?.[0];
            if (file) void handleUpload(file);
          }}", "ref": "{uploadInputRef}", "type": ""file""}

{"className": ""content-title-action"", "disabled": "{busyAction === "upload"}", "variant": ""primary"", "onClick": "{() =>
            review
              ? notify("审核模式保留示例素材，不执行真实上传")
              : uploadInputRef.current?.click()
          }"}

{"items": "{[
          { id: "全部", label: "全部" },
          { id: "video", label: "视频" },
          { id: "image", label: "图片" },
          { id: "audio", label: "音频" },
        ]}", "value": "{kind}", "onChange": "{(value) => {
          setKind(value as typeof kind);
          setPage(1);
        }}"}

{"aria-label": ""素材来源"", "value": "{source}", "onChange": "{(event) => {
              setSource(event.target.value as typeof source);
              setPage(1);
            }}"}

{"variant": ""primary"", "onClick": "{() => {
                    retainForDraft(selected);
                    patchDraft({
                      audioId: selected.id,
                      ipId: selected.personId,
                      voiceId: undefined,
                    });
                    navigate("oral-audio", { returnTo: "materials" });
                  }}"}

{"variant": ""outline"", "onClick": "{() => {
                    retainForDraft(selected);
                    patchDraft({
                      originalImageId: selected.id,
                      frameConfirmed: false,
                    });
                    navigate("replica", { returnTo: "materials" });
                  }}"}

{"variant": ""outline"", "onClick": "{() => {
                    retainForDraft(selected);
                    patchDraft({ firstFrameId: selected.id });
                    navigate("video", { returnTo: "materials" });
                  }}"}

{"variant": ""outline"", "onClick": "{() => {
                    retainForDraft(selected);
                    patchDraft({ tailFrameId: selected.id });
                    navigate("video", { returnTo: "materials" });
                  }}"}

{"aria-label": ""添加标签"", "onChange": "{(event) => setTagInput(event.target.value)}", "onKeyDown": "{(event) => {
                    if (event.key !== "Enter") return;
                    event.preventDefault();
                    addTag();
                  }}", "placeholder": ""输入标签后按 Enter"", "value": "{tagInput}"}

{"value": "{page}", "onChange": "{navigate}", "items": "{[
          { id: "replica", label: "视频复刻" },
          { id: "replacement", label: "人物置换" },
          { id: "video", label: "视频生成" },
          { id: "oral", label: "数字人口播" },
        ]}"}

{"items": "{[
          { id: "rewrite", label: "文案改写" },
          { id: "saved", label: "我的文案" },
        ]}", "value": "{tab}", "onChange": "{(value) => setTab(value as "rewrite" | "saved")}"}

{"aria-label": ""作品名称"", "className": ""creation-input"", "onChange": "{(event) =>
                  patchDraft({
                    script: {
                      ...state.draft.script,
                      title: event.target.value,
                      confirmed: false,
                    },
                  })
                }", "placeholder": ""作品名称"", "value": "{state.draft.script.title}"}

{"aria-label": ""二创文案"", "className": ""creation-textarea creation-copy-textarea"", "onChange": "{(event) =>
                  patchDraft({
                    script: {
                      ...state.draft.script,
                      text: event.target.value,
                      confirmed: false,
                    },
                  })
                }", "placeholder": ""在这里编辑乡墅口播文案"", "value": "{state.draft.script.text}"}

{"aria-label": ""拆解 Prompt"", "className": ""creation-textarea"", "onChange": "{(event) => {
                setPromptText(event.target.value);
                patchDraft({ prompt: event.target.value });
              }}", "placeholder": ""完成 AI 拆解后，这里会生成逐镜头的反推提示词；也可手动撰写。"", "rows": "{10}", "value": "{promptText}"}

{"accept": ""video/mp4,video/quicktime"", "aria-label": ""上传参考视频"", "hidden": "true", "onChange": "{(event) => {
          const file = event.target.files?.[0];
          if (file) void handleUpload(file);
          event.target.value = "";
        }}", "ref": "{uploadInputRef}", "type": ""file""}

{"aria-label": ""选择项目"", "className": ""creation-project-select"", "defaultValue": """", "onChange": "{(event) => {
                    const selected = data.projects.find(
                      (item) => item.id === event.target.value,
                    );
                    if (selected) {
                      patchDraft({ projectId: selected.id });
                      notify(`已切换到项目「${selected.name}」。`);
                    }
                  }}"}

{"key": "{item.id}", "type": ""button"", "onClick": "{() => {
                  onImport(item.prompt_text);
                  notify(`已导入「${item.name}」，可继续修改。`);
                  setOpen(false);
                }}"}

{"accept": ""image/png,image/jpeg"", "aria-label": "{`上传${label}`}", "hidden": "true", "onChange": "{(event) => {
          const file = event.target.files?.[0];
          if (file) void upload(file);
          event.target.value = "";
        }}", "ref": "{inputRef}", "type": ""file""}

{"items": "{[
          { id: "video", label: "文/图生视频" },
          { id: "reference", label: "参考生视频" },
        ]}", "value": "{referenceMode ? "reference" : "video"}", "onChange": "{(value) =>
          navigate(value === "reference" ? "reference" : "video")
        }"}

{"aria-label": "{`移除 ${asset.name}`}", "className": ""creation-reference-remove"", "onClick": "{() =>
                        patchDraft({
                          referenceIds: state.draft.referenceIds.filter(
                            (id) => id !== asset.id,
                          ),
                        })
                      }", "variant": ""quiet""}

{"items": "{[
              { id: "oral", label: "用文案生成" },
              { id: "oral-audio", label: "用已有音频生成" },
            ]}", "value": "{audioMode ? "oral-audio" : "oral"}", "onChange": "{(value) =>
              navigate(value === "oral-audio" ? "oral-audio" : "oral")
            }"}

{"type": ""button"", "className": ""studio-upload-icon"", "aria-label": ""上传视频"", "onClick": "{() => {
              if (review) {
                notify("审核示例不执行真实上传。");
                return;
              }
              fileInputRef.current?.click();
            }}"}

{"ref": "{fileInputRef}", "type": ""file"", "aria-label": ""选择视频文件"", "accept": "".mp4,.mov,video/mp4,video/quicktime"", "hidden": "true", "onChange": "{(event) => {
              const file = event.target.files?.[0];
              if (file) handleUploadFile(file);
              event.target.value = "";
            }}"}

{"type": ""button"", "className": ""studio-home-viral-cover"", "aria-label": "{`查看详情：${video.title}`}", "onClick": "{() =>
                      navigate("viral-detail", {
                        selectedVideoId: video.id,
                        returnTo: "workbench",
                      })
                    }"}

{"variant": ""quiet"", "aria-label": "{`用它复刻：${video.title}`}", "onClick": "{() => {
                        patchDraft({ sourceId: video.id });
                        navigate("replica", {
                          selectedVideoId: video.id,
                          returnTo: "workbench",
                        });
                      }}"}

{"value": "{status}", "onChange": "{setStatus}", "items": "{[
            { id: "all", label: "全部" },
            { id: "active", label: `进行中 ${activeCount}` },
            { id: "attention", label: `待处理 ${attentionCount}` },
            { id: "completed", label: "已完成" },
          ]}"}

{"variant": ""primary"", "onClick": "{() =>
                review
                  ? notify("示例账户，不保存真实资料。")
                  : openLive("profile")
              }"}

{"variant": ""outline"", "onClick": "{() => {
            patchDraft({ ipId: person.id });
            navigate("copy", { selectedPersonId: person.id });
          }}"}

{"variant": ""outline"", "onClick": "{() => {
              notify(`正在打开${person.name}的五视图与场景造型。`);
              openLive("characters");
            }}"}

{"variant": ""primary"", "onClick": "{() => {
              notify(`将在人物管理中为${person.name}选择并生成场景形象照。`);
              openLive("characters");
            }}"}

{"variant": ""outline"", "onClick": "{() => {
                    patchDraft({ ipId: person.id });
                    navigate("person-avatars", {
                      selectedPersonId: person.id,
                      selectedAssetId: asset.id,
                    });
                  }}"}

{"variant": ""primary"", "onClick": "{() => {
                    patchDraft({ ipId: person.id, imageId: asset.id });
                    navigate("replacement", {
                      selectedPersonId: person.id,
                      selectedAssetId: asset.id,
                    });
                  }}"}

{"variant": ""outline"", "onClick": "{() => {
                  patchDraft({ ipId: person.id, avatarId: avatar.id });
                  navigate(state.returnTo ?? "oral", {
                    selectedPersonId: person.id,
                  });
                }}"}

{"accept": "".mp4,.mov,video/mp4,video/quicktime"", "aria-label": ""选择人物视频"", "disabled": "{busy}", "type": ""file"", "onChange": "{(event) => {
                const file = event.target.files?.[0];
                if (file) void handleVideoUpload(file);
              }}"}

{"aria-label": ""确认分身克隆授权"", "checked": "{consented}", "disabled": "{review || busy}", "type": ""checkbox"", "onChange": "{(event) => {
              cloneSubmissionRef.current = undefined;
              setConsentedSourceId(
                event.target.checked ? source?.id : undefined,
              );
            }}"}

{"variant": ""primary"", "onClick": "{() => {
                    patchDraft({ ipId: person.id, voiceId: voice.id });
                    navigate(state.returnTo ?? "oral", {
                      selectedPersonId: person.id,
                      returnTo: undefined,
                    });
                  }}"}

{"accept": "".mp3,audio/mpeg"", "aria-label": ""选择声音样本"", "disabled": "{busy}", "type": ""file"", "onChange": "{(event) => {
                const file = event.target.files?.[0];
                if (file) void handleAudioUpload(file);
              }}"}

{"value": "{title}", "onChange": "{(event) => {
              setTitle(event.target.value);
              cloneSubmissionRef.current = undefined;
            }}", "placeholder": ""例如：张工本人音色 V2""}

{"aria-label": ""确认声音克隆授权"", "checked": "{consented}", "disabled": "{review || busy}", "type": ""checkbox"", "onChange": "{(event) => {
              cloneSubmissionRef.current = undefined;
              setConsentedSourceId(
                event.target.checked ? source?.id : undefined,
              );
            }}"}

{"type": ""button"", "key": "{asset.id}", "onClick": "{() => {
                      if (kind === "avatar-photo") {
                        select({ imageId: asset.id });
                        navigate("person-avatars", {
                          selectedPersonId: person?.id,
                          returnTo: state.page,
                        });
                        notify(
                          "已选择单张照片作为制作原料。照片尚不是口播分身，需完成制作后才能使用。",
                        );
                      } else
                        select(
                          kind === "image"
                            ? { imageId: asset.id }
                            : kind === "original-frame"
                              ? {
                                  originalImageId: asset.id,
                                  frameConfirmed: false,
                                }
                              : kind === "first-frame"
                                ? { firstFrameId: asset.id }
                                : kind === "tail-frame"
                                  ? { tailFrameId: asset.id }
                                  : kind === "audio"
                                    ? { audioId: asset.id, voiceId: undefined }
                                    : {
                                        referenceIds: [
                                          ...new Set([
                                            ...state.draft.referenceIds,
                                            asset.id,
                                          ]),
                                        ],
                                      },
                        );
                    }}"}

{"onClick": "{() => {
                onClose();
                navigate(
                  kind === "voice"
                    ? "person-voices"
                    : kind === "avatar"
                      ? "person-avatars"
                      : "people",
                  { selectedPersonId: person?.id, returnTo: state.page },
                );
              }}"}
